 data=p.evaluate("""()=>{const a=HonroApp,e=a.engine,b=e.b,C=HONRO_CORE,results=[],original=structuredClone(b);const cases=['unchanged','target-moved','terrain-damaged','terrain-broken','status-changed','actor-moved','rank-changed','skill-changed','angle-changed','power-changed','wind-changed','custom-map','modified-art'];for(const name of cases){Object.assign(b,structuredClone(original));const actor=e.active;actor.cls='archer';actor.angle=44;actor.loadout=['A01'];actor.ranks.A01=3;actor.acted=false;actor.retreat=false;let skill='A01',angle=44,power=.6;if(name==='target-moved'){const v=b.units.find(v=>v.side===1&&!v.dead);if(v){v.x=actor.x+220;v.y=actor.y;}}if(name==='terrain-damaged'){const t=b.terrain.find(t=>!t.broken&&!t.indestructible);if(t)t.hp=Math.max(1,t.hp*.4);b.sceneVersion++;}if(name==='terrain-broken'){const t=b.terrain.find(t=>!t.broken&&!t.indestructible);if(t)t.broken=true;b.sceneVersion++;}if(name==='status-changed'){actor.slowed={factor:.4,expires:8};actor.shield=33;const v=b.units.find(v=>v.side===1);if(v){v.curseTurns=3;v.shield=19;}}if(name==='actor-moved')actor.x+=67;if(name==='rank-changed')actor.ranks.A01=8;if(name==='skill-changed'){skill='A02';actor.loadout=[skill];actor.ranks[skill]=3;}if(name==='angle-changed')angle=actor.angle=12;if(name==='power-changed')power=.29;if(name==='wind-changed')b.wind+=9;if(name==='custom-map'){b.honroCustom=true;b.honroMapOrigin='workshop';}if(name==='modified-art'){const v=b.honroLandmarks.find(l=>l.asset?.vector)?.asset.vector;if(v)v.__qaChanged={nested:[1,2,3]};}for(const ignore of [false,true]){const before=JSON.stringify(b),rng=b.rng;let output;try{output={prediction:e.predict(actor,C.SKILLS[skill],angle,power,undefined,true,ignore)}}catch(err){output={error:String(err)}}results.push({name,ignore,output,unchanged:before===JSON.stringify(b),rngBefore:rng,rngAfter:b.rng});if(before!==JSON.stringify(b))throw Error('live mutation '+name);}}return {results,stage:b.honroStage};}""")
